import { defineApp } from "rwsdk/worker";
import { route } from "rwsdk/router";
import { env } from "cloudflare:workers";

export { ServerEntry, Document } from "./Document";

async function sha256Hex(bytes: Uint8Array): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", bytes);
  const hashArray = Array.from(new Uint8Array(digest));
  return hashArray.map((b) => b.toString(16).padStart(2, "0")).join("");
}

function getExtension(filename: string): string {
  const dot = filename.lastIndexOf(".");
  if (dot <= 0 || dot === filename.length - 1) return "";
  return filename.slice(dot + 1);
}

function jsonResponse(data: unknown, status = 200): Response {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "content-type": "application/json" },
  });
}

function getBucket(): R2Bucket {
  return env.BUCKET as unknown as R2Bucket;
}

export default defineApp([
  // POST /api/files - upload a file
  route("/api/files", {
    post: async ({ request }) => {
      let form: FormData;
      try {
        form = await request.formData();
      } catch {
        return jsonResponse({ error: "Invalid form data" }, 400);
      }
      const file = form.get("file");
      if (!file || typeof file === "string") {
        return jsonResponse({ error: "Missing 'file' field" }, 400);
      }
      // file is a File
      const filename = file.name || "";
      const ext = getExtension(filename);
      const arrayBuffer = await file.arrayBuffer();
      const bytes = new Uint8Array(arrayBuffer);
      const sha256 = await sha256Hex(bytes);
      const key = ext ? `uploads/${sha256}.${ext}` : `uploads/${sha256}`;

      const contentType = file.type || "application/octet-stream";

      await getBucket().put(key, bytes, {
        httpMetadata: {
          contentType,
        },
        customMetadata: {
          originalFilename: filename,
          sha256,
        },
      });

      return jsonResponse(
        {
          key,
          size: bytes.byteLength,
          contentType,
          sha256,
        },
        201,
      );
    },

    // GET /api/files - list all files
    get: async () => {
      const objects: Array<{
        key: string;
        size: number;
        uploaded: string;
      }> = [];
      let cursor: string | undefined = undefined;
      // R2 list requires the prefix to end with `/` if provided
      while (true) {
        const result = await getBucket().list({
          prefix: "uploads/",
          cursor,
        });
        for (const obj of result.objects) {
          objects.push({
            key: obj.key,
            size: obj.size,
            uploaded: obj.uploaded.toISOString(),
          });
        }
        if (!result.truncated || !result.cursor) break;
        cursor = result.cursor;
      }
      return jsonResponse({ objects });
    },
  }),

  // GET /api/files/:key - retrieve a file
  route("/api/files/:key", {
    get: async ({ params }) => {
      const key = decodeURIComponent(params.key as string);
      const obj = await getBucket().get(key);
      if (!obj) {
        return jsonResponse({ error: "Not found" }, 404);
      }
      const body = await obj.arrayBuffer();
      const headers = new Headers();
      const contentType =
        obj.httpMetadata?.contentType || "application/octet-stream";
      headers.set("content-type", contentType);
      headers.set("content-length", String(obj.size));
      return new Response(body, { status: 200, headers });
    },

    // DELETE /api/files/:key - delete a file
    delete: async ({ params }) => {
      const key = decodeURIComponent(params.key as string);
      // Check existence first to return 404 if not present
      const obj = await getBucket().get(key);
      if (!obj) {
        return jsonResponse({ error: "Not found" }, 404);
      }
      await getBucket().delete(key);
      return new Response(null, { status: 204 });
    },
  }),
]);
